def extract_images(p):
    def _imgs(x):
        d=(x.get('data') or x.get('data_preview') or {}) if isinstance(x,dict) else {}
        return d.get('images_results') or []
    if isinstance(p,dict) and isinstance(p.get('results'),list):
        out=[]
        for r in p['results']:
            out+=_imgs((r.get('response') or {}) if isinstance(r,dict) else {})
        return out
    return _imgs(p)
